// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2, ERC20} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;

    function setUp() public {
        c = new PuttyV2("", 0, address(this));
    }

    function testFuzz_property(
        uint256 warpTime,
        uint256 duration,
        uint256 premium,
        uint256 strike,
        uint256 nonce
    ) public {
        vm.assume(warpTime > 0 && warpTime < 1e12);
        duration = bound(duration, 1, 9_999 days);
        premium = bound(premium, 1, 1e18);
        strike = bound(strike, 1, 1e18);

        // Adversarial counterparties: an EIP-1271 maker that signs any hash,
        // and a fake ERC20 base asset whose transferFrom always succeeds.
        Maker1271 maker = new Maker1271();
        FakeERC20 baseAsset = new FakeERC20();

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        PuttyV2.ERC20Asset[] memory erc20Assets = new PuttyV2.ERC20Asset[](0);
        PuttyV2.ERC721Asset[] memory erc721Assets = new PuttyV2.ERC721Asset[](0);

        PuttyV2.Order memory order = PuttyV2.Order({
            maker: address(maker),
            isCall: true,
            isLong: true,
            baseAsset: address(baseAsset),
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: warpTime + 1_000 days,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        vm.warp(warpTime);

        bytes32 orderHash = c.hashOrder(order);
        uint256[] memory floorAssetTokenIds = new uint256[](0);

        bool ok;
        try c.fillOrder(order, "", floorAssetTokenIds) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok, "fillOrder should succeed");

        // General rule: after a successful fill, the long-side position's
        // recorded expiration is exactly block.timestamp + order.duration.
        assertTrue(
            c.positionExpirations(uint256(orderHash)) == block.timestamp + duration,
            "long position expiration must equal fill time + duration"
        );
    }
}

contract Maker1271 {
    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return this.isValidSignature.selector;
    }
}

contract FakeERC20 {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }

    function transfer(address, uint256) external pure returns (bool) {
        return true;
    }
}
